"""navera_lite/spoof.py — is this GPS lying? The spoofing tests of NAVERA Lite: the χ² test of a GPS fix against
an independent position (vision), persistence, the holes of the jump gate, and the guard that puts them
together in front of the judge. Part of NAVERA Lite, the course's teaching stack (mission 30).
Written for the course; it is not NAVERA code.

H0 = "the GPS is honest" (its error is only noise), H1 = "the GPS is spoofed" (an attacker added an offset).
The test statistic is the INNOVATION d² = rᵀ S⁻¹ r: r is the GPS position minus the independent position
(east, north metres), S = the GPS covariance + the reference's covariance (+ the distance the vehicle can fly
in the time between the two measurements). Under H0, d² follows a χ² law with 2 degrees of freedom:
P(d² > γ) = exp(−γ / 2).

How the guard plugs into the judge of mission 29 (GuardedArbiter, below): every estimate goes through
SpoofGuard.check() first. A REFUSED GPS fix reaches the judge as "no position" (valid=False), an IN_DOUBT one
with its covariance widened to the GPS–vision gap (so the judge calls it DEGRADED), a TRUSTED one unchanged.
The judge needs only Arbiter.receive(est, now_s) and Arbiter.step(now_s).
"""
import math
from dataclasses import replace

import numpy as np

from navera_lite.estimate import horizontal, stated_sigma
from navera_lite.geo import enu_flat, is_finite_latlon
from navera_lite.guard import JumpGate
from navera_lite.uncertainty import chi2_threshold, mahalanobis2

GUARD_DEFAULTS = {
    "p_fa": 0.01,           # false-alarm probability of ONE test: d² beyond chi2_threshold_2d(p_fa) "disagrees"
    "p_fa_far": 1e-6,       # the "clear disagreement" test (a far bigger gap)
    "doubt_n": 2,           # this many disagreeing reference fixes in a row → GPS IN_DOUBT
    "refuse_n": 5,          # this many in a row → GPS REFUSED (a slow drift)
    "far_n": 2,             # this many CLEAR disagreements in a row → GPS REFUSED (a jump the gate let through)
    "confirm_n": 2,         # a refused GPS comes back after this many agreeing reference fixes in a row
    "doubt_max_m": 500.0,   # a gap above this is more likely a wrong vision match: no "in doubt"
    "max_gap_s": 0.5,       # a reference fix is compared with the GPS fix closest in time, at most this far
    "ref_memory_s": 120.0,  # no stated reference heard for this long: the jump gate alone judges a refused GPS
}


# TODO 1 ---------------------------------------------------------------------------------------
def chi2_threshold_2d(p_fa):
    """The threshold γ of a test on a 2-D innovation, set by its FALSE-ALARM probability: an HONEST fix has
    d² > γ with probability p_fa (lesson §2). Mission 27's uncertainty.chi2_threshold(p, dof) gives the same
    kind of threshold, but from the probability p of being INSIDE the gate.

    p_fa: a probability, 0 < p_fa < 1 (else ValueError). Returns γ (no unit: d² is in "σ²").
    Example: chi2_threshold_2d(0.05) → 5.991 (5.99146…, mission 27's 95 % gate)
    """
    if not (isinstance(p_fa, (int, float)) and 0.0 < p_fa < 1.0):
        raise ValueError(f"p_fa must be a probability between 0 and 1, got {p_fa!r}")
    return chi2_threshold(1.0 - p_fa, dof=2)


# given — read it and use it, no need to change it
def p_value_2d(d2):
    """The probability that an honest 2-D innovation is at least as large as d2: exp(−d2 / 2).

    Example: p_value_2d(9.0) → 0.0111 (3 σ in 2-D: about one honest fix in 90, not 0.27 % as in 1-D)
    """
    return math.exp(-max(0.0, float(d2)) / 2.0)


# TODO 2 ---------------------------------------------------------------------------------------
def innovation(gps, ref, cfg):
    """The test statistic of one GPS fix against one independent position (lesson §3).

    gps, ref: Estimates (navera_lite.estimate). cfg: the settings (min_stated_sigma_m, max_speed_mps).
    r = where the GPS says minus where the reference says: (east, north) metres, geo.enu_flat FROM ref TO gps.
    S = the 2×2 horizontal covariance of gps + that of ref + g² on each axis (east and north), where
        g = cfg["max_speed_mps"] × |gps.stamp_s − ref.stamp_s| (how far the vehicle can fly between the two).
    Returns (d2, dist_m): d2 = rᵀ S⁻¹ r (mission 27's uncertainty.mahalanobis2) and dist_m = |r|; or None when
    gps or ref states no accuracy (estimate.stated_sigma() is None: nothing to test against — lesson §6).
    Example: gps 30 m east of ref, gps σ 3 m (cov a = c = 9), ref σ 15 m (a = c = 225), same stamp
             → (3.846, 30.0)   (S = 234 on each axis, d² = 900 / 234)
    """
    if stated_sigma(gps, cfg) is None or stated_sigma(ref, cfg) is None:
        return None
    e, n = enu_flat(ref.lat, ref.lon, gps.lat, gps.lon)
    r = np.array([e, n])
    a1, b1, c1 = horizontal(gps.cov)
    a2, b2, c2 = horizontal(ref.cov)
    g2 = (float(cfg["max_speed_mps"]) * abs(gps.stamp_s - ref.stamp_s)) ** 2
    S = np.array([[a1 + a2 + g2, b1 + b2], [b1 + b2, c1 + c2 + g2]])
    return mahalanobis2(r, S), float(math.hypot(e, n))


# TODO 3 ---------------------------------------------------------------------------------------
def first_alarm(stats, threshold, n):
    """Persistence (lesson §4): the index of the first test at which the last n test statistics were ALL
    above threshold — or −1 if that never happens.

    stats: a sequence of d² values, in time order; threshold: γ; n ≥ 1 (else ValueError).
    Example: first_alarm([1.0, 12.0, 13.0, 2.0, 11.0, 10.0, 15.0], 9.21, 3) → 6
    """
    if int(n) != n or n < 1:
        raise ValueError(f"n must be a whole number >= 1, got {n!r}")
    run = 0
    for i, v in enumerate(stats):
        run = run + 1 if v > threshold else 0
        if run >= n:
            return i
    return -1


# TODO 4 ---------------------------------------------------------------------------------------
def patient_accept_time(offset_m, speed_mps, v_max_mps, margin_m):
    """The jump gate's hole (lesson §1): the vehicle flies straight on at speed_mps; the spoofer jumps the GPS
    offset_m to the SIDE of the true track and keeps it there. The gate compares each fix with the last
    trusted one, dt seconds old, and accepts it once v_max_mps·dt + margin_m ≥ √((speed_mps·dt)² + offset_m²).
    Returns the smallest such dt in seconds (0.0 if the spoof is reachable at once), or math.inf if it never
    becomes reachable. Inputs are metres and m/s, all ≥ 0.
    Example: patient_accept_time(1000.0, 10.0, 20.0, 50.0) → 54.43 (54.425…);
             patient_accept_time(2000.0, 30.0, 30.0, 0.0) → inf
    """
    v, s, m, d = float(v_max_mps), float(speed_mps), float(margin_m), float(offset_m)
    if m >= d:
        return 0.0
    a = v * v - s * s
    b = 2.0 * v * m
    c = m * m - d * d
    if a < 0.0:
        return math.inf
    if a == 0.0:
        return -c / b if b > 0.0 else math.inf
    return (-b + math.sqrt(b * b - 4.0 * a * c)) / (2.0 * a)


# TODO 5 ---------------------------------------------------------------------------------------
def drift_alarm_time(drift_mps, sigma_s_m, threshold, n, period_s):
    """Detection delay of a slow drift, without noise (lesson §4): the spoofer pulls the GPS away at drift_mps
    from t = 0; a reference fix is tested at t = 0, period_s, 2·period_s, …; a test disagrees when the offset
    is beyond the test's radius sigma_s_m·√threshold (strictly); the alarm comes at the n-th disagreeing test
    in a row. Returns the alarm time in seconds after the drift started, or math.inf if drift_mps ≤ 0.
    sigma_s_m: the σ of the innovation on one axis (m), e.g. √(3² + 15²) for GPS 3 m and vision 15 m.
    Example: drift_alarm_time(2.5, 20.0, 5.99, 3, 1.0) → 22.0   (radius 48.9 m reached after 19.6 s:
             first disagreeing test at 20 s, the third in a row at 22 s)
    """
    if drift_mps <= 0:
        return math.inf
    t_cross = sigma_s_m * math.sqrt(threshold) / drift_mps
    k = math.floor(t_cross / period_s) + 1
    return (k + n - 1) * period_s


# given — this class is finished except its TODO methods
class SpoofGuard:
    """The GPS guard of NAVERA Lite: the jump gate (mission 01) + the χ² cross-check with an independent source
    of STATED accuracy, with persistence and re-acceptance (lesson §5's state diagram).

    check(est) → (verdict, reason) for any Estimate: a GPS fix gets its verdict "TRUSTED", "IN_DOUBT" or
    "REFUSED"; a fix of another source is a reference: it is tested against the GPS (on_reference) and the
    GPS's current verdict is returned. cfg: the settings (gps_timeout_s, max_speed_mps, gps_jump_margin_m,
    min_stated_sigma_m) plus the GUARD_DEFAULTS keys (missing keys take their default).
    Example: g = SpoofGuard(DEFAULTS); g.check(<first GPS fix>) → ("TRUSTED", "first fix")
    """

    def __init__(self, cfg):
        self.cfg = dict(GUARD_DEFAULTS)
        self.cfg.update(cfg)
        self.gamma = chi2_threshold_2d(self.cfg["p_fa"])          # "disagrees"
        self.gamma_far = chi2_threshold_2d(self.cfg["p_fa_far"])  # "clearly disagrees"
        self.gate = JumpGate(self.cfg)
        self.state, self.reason = "TRUSTED", "no GPS yet"
        self.refused_by = None         # "jump", "drift", "far" or "outage" while REFUSED
        self.disagree = 0              # reference fixes in a row with d² > gamma
        self.far = 0                   # reference fixes in a row with d² > gamma_far
        self.agree = 0                 # reference fixes in a row with d² <= gamma
        self.doubt_m = 0.0             # the gap (m) while IN_DOUBT
        self.history = []              # the GPS fixes received (all of them, refused ones too), oldest first
        self.last_gps_s = None         # stamp of the last GPS fix received
        self.last_ref_s = None         # stamp of the last reference fix that stated an accuracy
        self.last_test = None          # (d2, dist_m, ref source) of the last test, for messages

    # given — read it and use it, no need to change it
    def check(self, est):
        """The verdict on one estimate (see the class docstring)."""
        if est.source != "gps":
            self.on_reference(est)
            return self.state, self.reason
        if not est.valid or not is_finite_latlon(est.lat, est.lon):
            return self.state, "no position: nothing to judge"
        verdict = self.on_gps(est)
        self.history = [f for f in self.history if est.stamp_s - f.stamp_s <= 10.0] + [est]
        self.last_gps_s = est.stamp_s
        return verdict

    # given — read it and use it, no need to change it
    def closest_gps(self, t_s):
        """The GPS fix received whose stamp is closest to t_s, if at most max_gap_s away; else None."""
        best = min(self.history, key=lambda f: abs(f.stamp_s - t_s), default=None)
        if best is None or abs(best.stamp_s - t_s) > float(self.cfg["max_gap_s"]):
            return None
        return best

    # given — read it and use it, no need to change it
    def has_reference(self, t_s):
        """True if a reference of stated accuracy was heard at most ref_memory_s before t_s."""
        return self.last_ref_s is not None and t_s - self.last_ref_s <= float(self.cfg["ref_memory_s"])

    # given — read it and use it, no need to change it
    def set_state(self, state, reason, refused_by=None):
        """Change the verdict (and say why). Entering REFUSED empties the three counters: only reference fixes
        that come AFTER the refusal can confirm the GPS again."""
        if state == "REFUSED":
            self.refused_by = refused_by or self.refused_by
            self.disagree = self.far = self.agree = 0
        else:
            self.refused_by = None
        self.state, self.reason = state, reason
        return state, reason

    # TODO 6 -----------------------------------------------------------------------------------
    def on_reference(self, ref):
        """One reference fix (vision…) tests the GPS (lesson §4–§5). Returns d² of the test, or None when no
        test was possible. A test needs: ref valid and stating an accuracy (stated_sigma not None — then
        remember its stamp in self.last_ref_s), and a GPS fix close in time (self.closest_gps(ref.stamp_s)).
        Count the results in a row: self.disagree (d² > self.gamma), self.far (d² > self.gamma_far),
        self.agree (d² ≤ self.gamma) — a result of the other kind starts its counter again from 0.
        Then the verdict (self.set_state(state, reason, refused_by)), first rule that applies:
          REFUSED now:   self.agree ≥ confirm_n → "TRUSTED" ("confirmed by day: 2 fixes agree"), and that
                         GPS fix becomes the jump gate's trusted fix (self.gate.trusted)
          not REFUSED:   self.disagree ≥ refuse_n → "REFUSED", refused_by "drift"
                         self.far ≥ far_n         → "REFUSED", refused_by "far"
                         self.disagree ≥ doubt_n and the gap ≤ doubt_max_m → "IN_DOUBT" (self.doubt_m = the gap)
                         d² ≤ self.gamma          → "TRUSTED"
                         otherwise: no change (one disagreeing fix is not evidence)
        Example: after 4 reference fixes in a row with d² 12.0 (γ = 9.21 for p_fa 0.01), GPS "IN_DOUBT";
                 the 5th → "REFUSED" (refused_by "drift")
        """
        if not ref.valid or stated_sigma(ref, self.cfg) is None:
            return None
        self.last_ref_s = ref.stamp_s
        gps = self.closest_gps(ref.stamp_s)
        if gps is None:
            return None
        d2, dist = innovation(gps, ref, self.cfg)
        self.last_test = (d2, dist, ref.source)
        if d2 > self.gamma:
            self.disagree, self.agree = self.disagree + 1, 0
            self.far = self.far + 1 if d2 > self.gamma_far else 0
        else:
            self.disagree, self.far, self.agree = 0, 0, self.agree + 1
        if self.state == "REFUSED":
            if self.agree >= self.cfg["confirm_n"]:
                self.gate.trusted = gps
                self.set_state("TRUSTED", f"confirmed by {ref.source}: {self.agree} fixes agree (gap {dist:.0f} m)")
        elif self.disagree >= self.cfg["refuse_n"]:
            self.set_state("REFUSED", f"drifting away from {ref.source}: {self.disagree} fixes in a row disagree "
                                f"(gap {dist:.0f} m, d² {d2:.1f} > {self.gamma:.1f})", "drift")
        elif self.far >= self.cfg["far_n"]:
            self.set_state("REFUSED", f"far from {ref.source}: {self.far} fixes in a row (gap {dist:.0f} m, "
                                f"d² {d2:.1f} > {self.gamma_far:.1f})", "far")
        elif self.disagree >= self.cfg["doubt_n"] and dist <= self.cfg["doubt_max_m"]:
            self.doubt_m = dist
            self.set_state("IN_DOUBT", f"in doubt: {ref.source} disagrees by {dist:.0f} m "
                                       f"({self.disagree} fixes in a row)")
        elif d2 <= self.gamma:
            self.set_state("TRUSTED", f"agrees with {ref.source} (gap {dist:.0f} m, d² {d2:.1f})")
        return d2

    # TODO 7 -----------------------------------------------------------------------------------
    def on_gps(self, gps):
        """The verdict on one GPS fix (valid, finite: check() filtered the others), BEFORE it joins
        self.history. Returns self.set_state(…)'s (state, reason). The rules, first one that applies:
          1. the first GPS fix ever (self.last_gps_s is None): the jump gate takes it → "TRUSTED"
          2. back after an outage — more than cfg["gps_timeout_s"] since the last GPS fix — while the GPS is not
             REFUSED and a stated reference was heard (self.has_reference): "REFUSED", refused_by "outage"
             (jam, then spoof: only agreeing reference fixes may bring it back)
          3. REFUSED and a stated reference was heard: stay "REFUSED" (on_reference decides)
          4. REFUSED and no reference: the jump gate decides (self.gate.check) → "TRUSTED" if reachable again,
             else "REFUSED", refused_by "jump"
          5. TRUSTED or IN_DOUBT: the jump gate; a refused jump → "REFUSED", refused_by "jump"; else no change
        Example: TRUSTED at (lat, lon) at t = 10 s, then a fix 2 km away at t = 11 s (30 m/s, margin 50 m)
                 → ("REFUSED", "jump 2000 m > 80 m in 1.0 s")
        """
        if self.last_gps_s is None:
            ok, why = self.gate.check(gps)
            return self.set_state("TRUSTED", why)
        silent = gps.stamp_s - self.last_gps_s
        if silent > float(self.cfg["gps_timeout_s"]) and self.state != "REFUSED" and self.has_reference(gps.stamp_s):
            return self.set_state("REFUSED", f"back after {silent:.1f} s without GPS: waiting for "
                                       f"{self.cfg['confirm_n']} agreeing reference fixes", "outage")
        if self.state == "REFUSED":
            if self.has_reference(gps.stamp_s):
                return self.state, self.reason
            ok, why = self.gate.check(gps)
            if ok:
                return self.set_state("TRUSTED", "reachable again (no reference to ask): re-accepted")
            return self.set_state("REFUSED", why, "jump")
        ok, why = self.gate.check(gps)
        if not ok:
            return self.set_state("REFUSED", why, "jump")
        return self.state, self.reason


# given — read it and use it, no need to change it
def doubtful(est, gap_m):
    """An IN_DOUBT GPS fix as the judge must see it: the same fix, its horizontal variances raised to at least
    gap_m² ("no better than the gap", lesson §5), so its stated σ is the gap and the judge calls it DEGRADED.

    Example: doubtful(<GPS fix with a = c = 9>, 60.0).cov[0] → 3600.0
    """
    cov = list(est.cov)
    cov[0] = max(cov[0], gap_m * gap_m)
    cov[4] = max(cov[4], gap_m * gap_m)
    return replace(est, cov=tuple(cov), reason=f"in doubt: no better than {gap_m:.0f} m")


# given — read it and use it, no need to change it
class GuardedArbiter:
    """The judge of mission 29 with the spoofing guard in front of it (lesson "In NAVERA Lite").

    arbiter: any object with receive(est, now_s) and step(now_s) (mission 29's Arbiter); guard: a SpoofGuard.
    receive(est, now_s) → (verdict, reason) of the guard; the judge receives: a TRUSTED GPS fix unchanged, an
    IN_DOUBT one through doubtful(), a REFUSED one as "no position" (valid=False), every other source unchanged.
    step(now_s) → the judge's decision, unchanged.
    Example: j = GuardedArbiter(Arbiter(cfg), SpoofGuard(cfg)); j.receive(fix, 0.0) → ("TRUSTED", "first fix")
    """

    def __init__(self, arbiter, guard):
        self.arbiter, self.guard = arbiter, guard

    def receive(self, est, now_s):
        verdict, why = self.guard.check(est)
        if est.source == "gps" and est.valid:
            if verdict == "REFUSED":
                est = replace(est, valid=False, reason="refused: " + why)
            elif verdict == "IN_DOUBT":
                est = doubtful(est, self.guard.doubt_m)
        self.arbiter.receive(est, now_s)
        return verdict, why

    def step(self, now_s):
        return self.arbiter.step(now_s)
